"use client"

import { useState, useEffect } from "react"
import { useDictionary } from "@/components/dictionary-provider"
import { createClient } from "@/lib/supabase"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Plus, Package, Search, Pencil } from "lucide-react"
import { Input } from "@/components/ui/input"

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Save, X, Pencil, Loader2 } from "lucide-react"
import { Switch } from "@/components/ui/switch"

import { SectionLoader } from "@/components/section-loader"
import { notify } from "@/lib/notifications"
import { usePersistedState } from "@/hooks/use-persisted-state"

import { formatCurrency, formatNumber } from "@/lib/formatters"

export default function ProductsPage() {
  const { dict, config } = useDictionary()
  const supabase = createClient()
  const [products, setProducts] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [isOpen, setIsOpen] = usePersistedState("products_dialog_open", false)
  const [editingProduct, setEditingProduct] = usePersistedState<any>("products_editing_data", null)

  const [formData, setFormData] = usePersistedState("products_form_data", {
    sku: "",
    name: "",
    base_price: 0
  })

  const [rowLoading, setRowLoading] = useState<Record<string, boolean>>({})

  const toggleActive = async (id: string, currentStatus: boolean) => {
    setRowLoading(prev => ({ ...prev, [id]: true }))
    try {
      const { error } = await supabase
        .from("products")
        .update({ is_active: !currentStatus })
        .eq("id", id)

      if (error) throw error
      
      setProducts(prev => prev.map(p => 
        p.id === id ? { ...p, is_active: !currentStatus } : p
      ))
      notify.success("Status Updated", `Product is now ${!currentStatus ? 'Active' : 'Inactive'}`)
    } catch (err: any) {
      console.error("Products: Toggle active error:", err)
      notify.error("Update Failed", err.message)
    } finally {
      setRowLoading(prev => ({ ...prev, [id]: false }))
    }
  }

  // Helper to parse formatted string back to number
  const parseNumber = (val: string) => {
    return parseFloat(val.replace(/,/g, '')) || 0
  }

  async function fetchProducts() {
    setLoading(true)
    try {
      const { data, error } = await supabase
        .from("products")
        .select("*")
        .order('created_at', { ascending: false })

      if (error) {
        console.error("Products: Fetch error:", error)
        notify.error("Data Fetch Failed", error.message)
        setProducts([])
      } else if (data) {
        setProducts(data)
      }
    } catch (err) {
      console.error("Products: Unexpected fetch exception:", err)
      setProducts([])
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchProducts()
  }, [])

  const handleOpenDialog = (product: any = null) => {
    if (product) {
      setEditingProduct(product)
      setFormData({
        sku: product.sku,
        name: product.name,
        base_price: product.base_price
      })
    } else {
      setEditingProduct(null)
      setFormData({ sku: "", name: "", base_price: 0 })
    }
    setIsOpen(true)
  }

  const handleSubmit = async (e: React.SyntheticEvent<HTMLFormElement, SubmitEvent>) => {
    e.preventDefault()
    const payload = { ...formData }

    try {
      if (editingProduct) {
        const { error } = await supabase.from("products").update(payload).eq("id", editingProduct.id)
        if (error) throw error
        notify.success("Success", "Product updated successfully")
      } else {
        const { error } = await supabase.from("products").insert([payload])
        if (error) throw error
        notify.success("Success", "Product created successfully")
      }
      setIsOpen(false)
      fetchProducts()
    } catch (err: any) {
      console.error("Products: Save error:", err)
      notify.error("Save Failed", err.message || "An unexpected error occurred")
    }
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">{dict.TITLE_PRODUCTS}</h1>

        <Dialog open={isOpen} onOpenChange={setIsOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => handleOpenDialog()}>
              <Plus data-icon="inline-start" />
              {dict.TITLE_ADD_PRODUCT}
            </Button>
          </DialogTrigger>
          <DialogContent className="w-[350px]">
            <DialogHeader>
              <DialogTitle>
                {editingProduct ? dict.TITLE_EDIT_PRODUCT : dict.TITLE_ADD_PRODUCT}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="flex flex-col gap-4 p-5">
              <div className="flex flex-col gap-2">
                <Label htmlFor="sku">{dict.LABEL_SKU}</Label>
                <Input
                  id="sku"
                  value={formData.sku}
                  onChange={(e) => setFormData({ ...formData, sku: e.target.value })}
                  placeholder="OIL-001"
                  required
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="name">{dict.LABEL_PRODUCT_NAME}</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="Diesel Premium"
                  required
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="base_price">{dict.LABEL_BASE_PRICE}</Label>
                <Input
                  id="base_price"
                  type="text"
                  inputMode="decimal"
                  className="text-right font-mono"
                  value={formatNumber(formData.base_price)}
                  onChange={(e) => {
                    const val = e.target.value.replace(/[^0-9.]/g, '')
                    setFormData({ ...formData, base_price: parseNumber(val) })
                  }}
                  required
                />
              </div>
              <DialogFooter className="mt-2 gap-2 *:w-full *:flex-1 h-22 sm:h-auto">
                <Button type="button" variant="outline" onClick={() => setIsOpen(false)} className="flex-1">
                  <X data-icon="inline-start" />
                  {dict.BUTTON_CANCEL}
                </Button>
                <Button type="submit" className="">
                  <Save data-icon="inline-start" />
                  {dict.BUTTON_SAVE}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <div className="action-bar">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
          <Input
            placeholder={dict.SEARCH_PLACEHOLDER}
            className="pl-8"
          />
        </div>
      </div>

      <Card className="data-card">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead><Package className="size-4 mr-2 inline-block" />{dict.LABEL_NAME}</TableHead>
              <TableHead>{dict.LABEL_SKU}</TableHead>
              <TableHead className="text-right">{dict.LABEL_BASE_PRICE}</TableHead>
              <TableHead className="text-right">{dict.LABEL_ACTIONS}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={4} className="p-0">
                  <SectionLoader />
                </TableCell>
              </TableRow>
            ) : products.length === 0 ? (
              <TableRow><TableCell colSpan={4} className="text-center py-8">{dict.NO_DATA}</TableCell></TableRow>
            ) : (
              products.map((product) => (
                <TableRow key={product.id}>
                  <TableCell className="font-medium">{product.name}</TableCell>
                  <TableCell>{product.sku}</TableCell>
                  <TableCell className="text-right font-sans">{formatCurrency(product.base_price)}</TableCell>
                  <TableCell className="text-right">
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => handleOpenDialog(product)}
                    >
                      <Pencil className="size-4 md:mr-2" />
                      <span className="hidden md:inline">{dict.BUTTON_EDIT}</span>
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>
    </div>
  )
}